<template>
 <div class="dashboard" :style="{width:'100%','--board-height':height+'px'}" v-loading="loading">
  <header class="dashboard-header"><div class="brand"><span class="brand-mark"><i/><b/></span><strong>贵金属加工系统</strong></div><div class="dashboard-factory"><span>数据范围</span><el-select-v2 v-model="selectedFactory" class="el-select" aria-label="看板工厂" filterable :options="dashboardFactoryOptions" :disabled="!canSelectAll||!factoryOptions.length" placeholder="所属工厂" @change="load"/></div><div class="header-right"><el-button class="backend-button" :disabled="!managementPath" @click="router.push(managementPath)">后台管理</el-button><el-dropdown trigger="click" placement="bottom-end" @command="logout"><span class="profile" role="button" tabindex="0" aria-label="账户菜单"><span class="avatar"><i/><b/></span>{{user.nickName||user.name}}</span><template #dropdown><el-dropdown-menu><el-dropdown-item command="logout">退出登录</el-dropdown-item></el-dropdown-menu></template></el-dropdown></div></header>
  <main><div class="page-title"><h1>数据看板</h1><span>生产进度与金属损耗概览</span></div><div v-if="failed" class="load-error">数据加载失败 <el-button link @click="load">重新加载</el-button></div>
