   <div class="board-grid"><DashboardProductionProgress :factory-id="selectedFactory" :ready="optionsReady"/><div class="top-charts"><section class="chart-card trend-card"><h2>近30日金属损耗趋势</h2><div ref="trendEl" class="dashboard-chart"/><span v-if="!hasTrend" class="empty-overlay">近30日暂无已结算损耗</span></section><section class="chart-card"><h2>本月工序损耗排行TOP5 <span>单位：g</span></h2><div ref="rankingEl" class="dashboard-chart"/><span v-if="!data.ranking?.length" class="empty-overlay">本月暂无工序损耗</span></section></div>
