 create(trendEl.value,{color:[blue],legend:{top:0,data:['铱Ir']},tooltip:{trigger:'axis',valueFormatter:v=>decimalText(v)+' g'},grid:{left:55,right:25,top:50,bottom:35},xAxis:{type:'category',boundaryGap:false,data:(d.trend||[]).map((x:any)=>x.day.slice(5))},yAxis:{type:'value',name:'g',min:0},series:[{name:'铱Ir',type:'line',symbolSize:4,data:(d.trend||[]).map((x:any)=>Number(x.loss)),lineStyle:{width:2}}]})
